import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const CHANNELS = ['포털', '메신저', '모바일', '대화방', '메일'];

function idText(value: unknown, label: string): string {
  const text = typeof value === 'number' || typeof value === 'string' ? String(value).trim() : '';
  if (!/^[0-9]+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '은(는) 숫자여야 합니다.');
  }
  return text;
}

function requiredText(value: unknown, label: string, max: number): string {
  const text = typeof value === 'string' ? value.trim() : '';
  if (text === '') {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '을(를) 입력해 주세요.');
  }
  if (text.length > max) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '은(는) ' + max + '자 이하로 입력해 주세요.');
  }
  return text;
}

@Controller('api/v1')
export class FnSfr03606Controller {
  @Post('/notifications')
  @HttpCode(200)
  async createNotification(@Req() req: Request) {
    const user = currentUser(req);
    user.require('로그인 사용자');
    const data = checks.inputOf(req.body);
    const recipientId = idText(data['recipientId'], '수신자');
    const title = requiredText(data['title'], '알림 제목', 200);
    const eventType = requiredText(data['eventType'], '알림 이벤트 유형', 50);
    const targetType = requiredText(data['targetType'], '바로가기 대상 유형', 50);
    const targetId = idText(data['targetId'], '바로가기 대상 ID');
    const channel = requiredText(data['channel'], '알림 채널', 10);
    if (!CHANNELS.includes(channel)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '알림 채널은 포털, 메신저, 모바일, 대화방, 메일 중 하나여야 합니다.');
    }
    return transaction(async (db) => {
      const employees = await db.query(
        'SELECT employee_id FROM employee WHERE employee_id = CAST(:recipientId AS bigint)',
        { recipientId },
      );
      if (employees.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '알림 대상자를 찾을 수 없습니다.');
      }
      const rows = await db.query(
        'INSERT INTO notification (recipient_id, channel, title, read_status, event_type, target_type, target_id, created_at, updated_at) ' +
          'VALUES (CAST(:recipientId AS bigint), :channel, :title, :readStatus, :eventType, :targetType, CAST(:targetId AS bigint), now(), now()) ' +
          'RETURNING notification_id AS "notificationId"',
        { recipientId, channel, title, readStatus: '안읽음', eventType, targetType, targetId },
      );
      return { notificationId: Number(rows[0]['notificationId']) };
    });
  }
}

